import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
/**
 * Defines passthrough(pt) options type in SidebarContent component.
 */
export type SidebarContentPassThroughType<E> = PassThroughType<SidebarContentInstance, E>;
/**
 * Defines passthrough(pt) options of SidebarContent component.
 */
export interface SidebarContentPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SidebarContentPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in SidebarContent component.
 */
export interface SidebarContentProps extends BaseComponentProps<SidebarContentInstance, unknown, SidebarContentPassThrough> {
}
/**
 * Defines valid state in SidebarContent component.
 */
export interface SidebarContentState {
}
/**
 * Defines the methods and properties exposed by SidebarContent component.
 */
export interface SidebarContentExposes {
}
/**
 * Instance of SidebarContent component.
 */
export type SidebarContentInstance = ComponentInstance<SidebarContentProps, SidebarContentState, SidebarContentExposes>;
